# Debug the problematic rows more carefully
demo_input = [
    [4, 7, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],  # Row 7
    [4, 7, 5, 8, 8, 5, 4, 7, 8, 8, 7, 5],  # Row 19
    [4, 5, 5, 8, 8, 5, 4, 5, 8, 8, 8, 8],  # Row 20
]

# Extract all non-8 values from each row to see full structure
for i, row in enumerate(demo_input):
    non_8 = [(c, v) for c, v in enumerate(row) if v != 8]
    print(f"Row {i}: Non-8 positions: {non_8}")

    # Look at the full row to identify potential period
    vals = row[:12]
    print(f"  Full values: {vals}")

    # Try to detect period
    for p in range(2, 6):
        match = True
        for j in range(len(vals)):
            if j >= p and vals[j] == vals[j % p]:
                pass
            elif vals[j] != vals[j % p]:
                # Check if it could be 8 (empty cell)
                if vals[j] != 8 and vals[j % p] != 8:
                    match = False
                    break
        if match and len(non_8) >= 2 * p:
            print(f"  Possible period: {p} -> pattern = {vals[:p]}")

print("\n\nNow checking expected output patterns:")
