    [4, 7, 5, 4, 7, 4, 7, 5, 4, 7, 5, 5],  # Row 7
    [4, 7, 5, 4, 7, 4, 7, 5, 4, 7, 5, 5],  # Row 19  
    [4, 5, 5, 4, 5, 4, 5, 5, 4, 5, 5, 5],  # Row 20
]

for i, row in enumerate(expected_rows):
    vals = row[:12]
    print(f"Expected Row {i}: {vals}")
    for p in range(2, 6):
        match = True
        for j in range(len(vals)):
            if vals[j] != vals[j % p]:
                match = False
                break
